14	std::string sha256_hex(const std::string& bytes)
15	{
16	    std::array<unsigned char, SHA256_DIGEST_LENGTH> digest{};
17	    SHA256(reinterpret_cast<const unsigned char*>(bytes.data()), bytes.size(), digest.data());
18	    std::ostringstream out;
19	    out << std::hex << std::setfill('0');
20	    for (unsigned char byte : digest)
21	        out << std::setw(2) << static_cast<unsigned int>(byte);
22	    return out.str();
23	}
24	
25	std::optional<std::string> manufacturing_input_hash(const Workspace::WorkspaceSnapshot& snapshot,
26	                                                    std::size_t                         plate_index)
27	{
28	    if (plate_index >= snapshot.plates.size())
29	        return std::nullopt;
30	
31	    const Workspace::WorkspacePlate& plate = snapshot.plates[plate_index];
32	    json objects = json::array();
33	    for (const Workspace::WorkspaceObject& object : plate.objects) {
34	        json instances = json::array();
35	        for (const Workspace::ObjectTransform& transform : object.instances)
36	            instances.push_back(json{{"position", transform.position},
37	                                     {"rotation", transform.rotation},
38	                                     {"scale", transform.scale}});
39	        // Object display names and session-scoped IDs are intentionally not
40	        // manufacturing inputs. Geometry changes exposed by this workspace
41	        // surface appear as object/instance topology or transforms.
42	        objects.push_back(json{{"instances", std::move(instances)}});
43	    }
44	    const json canonical{{"format", "jusprin-manufacturing-input-v1"},
45	                         {"plateIndex", plate_index},
46	                         {"printerPreset", snapshot.setup.printer_preset},
47	                         {"materialPreset", snapshot.setup.filament_preset},
48	                         {"objects", std::move(objects)}};
49	    return sha256_hex(canonical.dump());
50	}
51	
52	std::optional<SentRecord> sent_record(const Workspace::WorkspaceSnapshot& snapshot, std::size_t plate_index)
53	{
54	    const std::optional<std::string> hash = manufacturing_input_hash(snapshot, plate_index);
55	    if (!hash)
56	        return std::nullopt;
57	    const Workspace::WorkspacePlate& plate = snapshot.plates[plate_index];
58	    SentRecord record;
59	    record.plate_index              = plate_index;
60	    record.plate_name               = plate.name;
61	    record.printer                  = snapshot.setup.printer_preset;
62	    record.material                 = snapshot.setup.filament_preset;
63	    record.manufacturing_input_hash = *hash;
64	    // An estimate OrcaSlicer did not give stays zero, which the ledger reads
65	    // as not recorded.
66	    if (plate.estimate) {
67	        if (plate.estimate->has_time)
68	            record.statistics.print_time_seconds = plate.estimate->print_time_seconds;
69	        if (plate.estimate->has_material)
70	            record.statistics.material_grams = plate.estimate->material_grams;
71	        if (plate.estimate->has_cost)
72	            record.statistics.material_cost = plate.estimate->material_cost;
73	    }
74	    return record;
75	}
