    record.outcome                  = entry.value("outcome", "");
    record.failure                  = entry.value("failure", "");
    record.sent_id                  = entry.value("sentId", "");
    record.project_id               = entry.value("projectId", "");
    record.conversation_id          = entry.value("conversationId", "");
