std::string ProjectStateDocument::add_sent(SentRecord record, const std::string& timestamp)
{
    const std::uint64_t number = m_doc["counters"].value("nextSent", std::uint64_t(1));
    m_doc["counters"]["nextSent"] = number + 1;
